insert into farmacia.servicos (id, icone, titulo, resumo, texto, ordem) values
  ('farmacia-popular', 'escudo', 'Farmácia Popular', 'Medicamentos gratuitos ou com desconto pelo programa do Ministério da Saúde.', 'A rede é credenciada ao programa e trabalha com os principais laboratórios nele incluídos. São gratuitos os medicamentos para hipertensão, diabetes e asma, e têm desconto os de dislipidemia, osteoporose, rinite, glaucoma, doença de Parkinson e anticoncepcionais. Leve documento com foto, CPF e a receita dentro da validade.', 0),
  ('injecoes', 'escudo', 'Injeções', 'Aplicação de injetáveis em sala apropriada, por profissional qualificado.', 'As lojas têm local reservado e equipe habilitada para aplicar medicamentos injetáveis. Traga a receita e o medicamento. Consulte a unidade mais próxima para confirmar os horários em que o serviço está disponível.', 1),
  ('afericoes', 'relogio', 'Aferições', 'Medição de pressão arterial e de glicose com equipe especializada.', 'Acompanhamento de rotina para quem controla pressão ou diabetes, feito por equipe treinada. É um serviço de acompanhamento: não substitui consulta médica nem exame laboratorial.', 2),
  ('pbm', 'medicamentos', 'PBM', 'Mais de 3.000 medicamentos de marca e genéricos com desconto de laboratório.', 'Os Programas de Benefício em Medicamentos aplicam o desconto do próprio laboratório direto no balcão, mediante cadastro e apresentação da receita. A rede trabalha com mais de 3.000 medicamentos de marca e genéricos para os mais variados tratamentos.', 3),
  ('convenios', 'cartao', 'Convênios', 'Descontos por convênio particular ou empresarial.', 'Empresas e entidades conveniadas garantem desconto a funcionários e associados, com compra identificada e desconto em folha quando o convênio prevê. Consulte se o seu convênio já é atendido pela rede.', 4),
  ('plantao', 'relogio', 'Atendimento 24 horas', 'Duas unidades de plantão, para quando a necessidade não espera.', 'Planalto Verde, em Ribeirão Preto, e a unidade 24 Horas, em Pirassununga, atendem em regime de plantão, todos os dias. As demais lojas funcionam diariamente das 7h às 23h.', 5),
  ('entrega', 'caminhao', 'Disk Entrega', 'Medicamentos e perfumaria entregues em casa, pedidos pelo WhatsApp.', 'Hoje o pedido é feito por telefone ou WhatsApp e passa por um atendente. Com a loja online, o mesmo pedido pode ser fechado pelo próprio cliente, a qualquer hora, com o frete calculado pelo CEP e sem ocupar ninguém no balcão.', 6),
  ('recarga', 'celular', 'Recarga de celular', 'Recarga das principais operadoras, na hora.', 'Recarga de crédito pré-pago das principais operadoras de telefonia móvel, feita no caixa em poucos segundos.', 7),
  ('estacionamento', 'carro', 'Estacionamento próprio', 'Todas as lojas da rede têm estacionamento para clientes.', 'Todas as unidades contam com estacionamento próprio, o que facilita a compra de volume e a retirada de pedidos feitos pelo site.', 8)
