insert into farmacia.avaliacoes (produto_sku, autor_nome, nota, titulo, texto, verificada, criado_em) values
  ('LUM-CPH-250', 'Camila R.', 5, 'Meu cabelo voltou a ter brilho', 'Uso há dois meses depois de uma progressiva que ressecou tudo. O desembaraço mudou completamente e não pesa, mesmo eu tendo cabelo fino.', true, '2026-08-28'::timestamptz),
  ('LUM-CPH-250', 'Juliana M.', 5, 'Rende muito', 'Um pote dura bastante porque precisa de pouquíssimo produto. Cheiro discreto, não enjoa.', true, '2026-08-14'::timestamptz),
  ('LUM-CPH-250', 'Patrícia L.', 4, 'Bom, mas o preço subiu', 'Produto excelente para cabelo cacheado, define sem deixar duro. Tirei uma estrela só porque achei caro fora de promoção.', true, '2026-07-30'::timestamptz),
  ('LUM-CPH-250', 'Renata S.', 5, 'Recomendo para cabelo cacheado', 'Faço fitagem com ele e os cachos ficam definidos o dia todo, sem frizz. Chegou bem embalado e dentro do prazo.', false, '2026-07-11'::timestamptz),
  ('LUM-CPH-250', 'Ana Beatriz', 4, 'Cumpre o que promete', 'Hidrata bem e o cabelo fica sedoso. Senti falta de uma embalagem com válvula pump, mas o produto em si é ótimo.', true, '2026-06-22'::timestamptz);
